"""Original editable regional quest arcs; no external assets or provider jobs."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[2]
campaign=json.loads((root/'game/data/campaign.json').read_text())
# Two discoverable places, local supply problem, and the guardians' competing priorities.
arcs={
'ravenwood':('Springward Cairn','Thornwatch Signal','Clear water runs beneath the sick roots. Someone has bound the spring with a strip of watch-cloth.','A broken watch horn lies beside tracks leading toward the Hollow Oak.','Blackthorn’s pathfinders need timber for warning posts, not another expedition lost in the trees.','seasoned_wood',3,'Keep the woodland routes open','Reinforce Blackthorn’s watch','A road is a promise to those who must walk it.','A safe home gives every traveler somewhere to return.'),
'frostpeaks':('The Unlit Beacon','Glacier Names','The beacon is cold, but its wick is new. Its keeper left willingly.','Names carved into blue ice belong to watchkeepers still living in Icehelm.','Beacon crews cannot reach the high towers without fresh repair metal.','iron_ingot',3,'Guide the stranded climbers','Hold the glacier watch','No beacon matters if we abandon the people below it.','A watch kept through one more night may save the whole valley.'),
'stormcrown':('Windcaller Bell','The Bent Standard','The bell moves without sounding. Its clapper points toward the storm.','A watch standard has bent toward the peak against the wind.','The ascent has shredded the straps carrying the watch’s supplies.','leather_strip',3,'Reopen the mountain road','Rebuild the summit watch','Let the storm test us; it must not divide us.','We will put the watch back where the wind can see it.'),
'ashen':('The Ash Gauge','Cooling Channel','The lava has risen past marks cut by three generations of furnace workers.','A cold channel steams with no water in it. The caldera’s pressure is turning inward.','Ashenreach’s channel gates need new fittings before the next surge.','iron_ingot',4,'Protect the furnace workers','Strengthen the caldera gates','Fire serves people. It should never demand them.','We can hold the mountain, one repaired gate at a time.'),
'marsh':('Reedkeeper Post','The Sinking Shrine','A basket tied above the water holds the last dry seed from a flooded garden.','Offerings float upward through a shrine whose floor is sinking.','Wickermoor needs planks for the raised walks before another house is cut off.','seasoned_wood',4,'Save the isolated households','Fortify Wickermoor’s walks','A village is every home we can still reach.','Then we build paths the water cannot take.'),
'silvermere':('The False Light','Saltglass Marker','A shard of the lighthouse lens catches sunlight from the wrong direction.','Salt has sealed a warning scratched into the old keeper’s stone.','Silverkeep’s light crew needs metal braces to reset the great lens.','iron_ingot',3,'Guide ships into harbor','Guard the lighthouse','The light belongs to everyone who trusts it.','Then no one will turn it against them again.'),
'eldergrove':('Seedkeeper Circle','The Listening Root','Tiny shoots grow inside a ring no animal will cross.','The roots tremble when you speak a name, then settle when you listen.','The grove’s wandering keepers need bindings to carry injured animals out of the blight.','leather_strip',3,'Reopen the pilgrims’ paths','Shelter the seedkeeper circle','No city owns this place. Its paths must remain open.','And the living heart must remain whole.'),
'iron_plains':('The Abandoned Plow','Siege Survey','A plow was forged from an old spear. Its blade has begun pointing toward the bastion.','Every abandoned engine faces the same farm road.','Harrowstead’s farmers need timber to turn the siege trenches into bridges.','seasoned_wood',4,'Return the fields to farmers','Restore the bastion watch','We did not win a homeland just to march over it.','The strongest wall is the one that lets the harvest pass.'),
'shadowfen':('The Cold Lantern','Webkeeper Hollow','The lantern flame casts two shadows. Neither belongs to you.','Threads stretched across a hollow carry the voices of missing travelers.','There is no town here; a passing rescue party needs dry wood for true signal fires.','seasoned_wood',3,'Mark a safe trail','Watch the false lights','Leave one honest light and someone will find their way.','I will stay until the false ones go dark.'),
'drakeshard':('The Singing Shard','Old Scale Oath','The shard’s note changes when you turn toward the vault.','A dragon oath is cut into stone beneath a hunter’s later boast.','Ironhold’s climbers need new straps to carry the wounded down Bloodspine Pass.','leather_strip',4,'Bring the hunters home','Keep the scale oath','A trophy is worth less than the hunter carrying it.','An oath is worth only what we protect in its name.'),
'westreach':('The Bell Rope','Wreckers’ Ledger','The rope is wet with seawater though the tide cannot reach it.','The ledger lists ships that have not yet sailed.','Westhaven’s salvage crew needs iron hooks to pull wreckage out of the safe channel.','iron_ingot',3,'Clear the merchant passage','Keep watch over the harbor','Let the harbor earn its living without another wreck.','And let every ship know someone is keeping watch.'),
'deadwind':('The Last Lamp','Names in Dust','A lamp burns beside boots whose owner left no footprints.','The same name is written again and again beneath the dust.','Duskwatch’s lamplighters need dry wood to shelter the last road lamps.','seasoned_wood',3,'Guide the living through','Keep faith with the lost','We can remember them without joining them.','Then we carry their names into the morning.'),
'ravenford':('The Torn Oath','The Crownroad Seal','The oath’s missing line promises service to the people, not the crown.','The seal has split exactly where the royal road leaves the capital.','Ravenford’s wardens need leather bindings to preserve the recovered oath tablets.','leather_strip',3,'Open the crownroad','Guard the people’s oath','A road closed to the people is no royal road at all.','Then the oath will name them first.'),
'cursed_mire':('The Broken Chain','Soulwater Cairn','A chain link rings when held above the black water.','The cairn’s stones bear the marks of armies from opposing sides.','No village survives here. A burial party needs bindings to carry remains out of the water.','leather_strip',4,'Release the wandering dead','Watch the soulwater crossings','No more armies should be fed to this place.','We will remember why the crossing must be guarded.'),
'golden':('The False Horizon','The Buried Lens','The horizon moves with the lens even when the sun stands still.','A second lens is buried facing the first, turning daylight into a closed circle.','Sunspire’s caravan guides need straps to carry water past the mirage dunes.','leather_strip',3,'Reopen the caravan route','Protect the observatory','A true horizon gives everyone a direction.','And a guarded lens keeps it true.'),
'dragons_rest':('The Warm Shell','The Ashwing Perch','The shell is warm. A new brood is sleeping under the ash.','Old scorch marks end around a circle of untouched nesting stone.','Cinderport needs timber to repair landing stages for the roost’s supply boats.','seasoned_wood',4,'Protect the coastal travelers','Shelter the sleeping brood','People and dragons can share a coast without sharing a war.','Then we guard the places where that peace begins.'),
'mistvale':('The Wrong Reflection','The Returning Ribbon','Your reflection raises its hand before you do. It points along the path.','A ribbon tied upstream returns on water flowing the other way.','Mistvale’s guides need wooden markers that can be recognized from either direction.','seasoned_wood',3,'Mark the honest paths','Watch the Mirrorwell','A path can change without leaving its travelers behind.','Someone must remain to tell the reflection from the road.'),
'hollow_isles':('The Nameless Crown','Memory Shore','The crown is light as driftwood. Every jewel reflects a different face.','Footsteps appear in the sand where the lost kingdom’s road once stood.','Hollowguard’s archivists need metal clasps to hold the recovered memory tablets.','iron_ingot',4,'Share the kingdom’s memory','Guard the last throne','A kingdom remembered by everyone cannot vanish again.','Then its last throne will serve as a witness, not a ruler.')}
quests={};sites={};dialogue={}
for region,row in arcs.items():
 r=campaign['regions'][region];a,b,lore_a,lore_b,need,material,quantity,choice_a,choice_b,line_a,line_b=row
 sites[region]=[
  {'id':region+':first','name':a,'room':'spring' if region=='ravenwood' else 'forest','z':6.0,'text':lore_a},
  {'id':region+':second','name':b,'room':'ruins' if region=='ravenwood' else 'crossing','z':7.0,'text':lore_b}]
 pair=[campaign['heroes'][i] for i in r['hero_pair']]
 dialogue[region]={'before':r['hook']+' '+pair[0]['name']+' asks you to read the signs along the road. '+pair[1]['name']+' is preparing the last defenses.','after':r['boss']+' is defeated. The anchor is steady, but the roads and the people still need help.','voices':[line_a,line_b]}
 entries=[
 ('signs','Read the land','Survey '+a+' and '+b+'.',{'kind':'sites','ids':[s['id'] for s in sites[region]]},[],{'gold':45,'items':{'potion':2}},lore_a+' '+lore_b),
 ('supplies','A road worth keeping',need,{'kind':'delivery','item':material,'quantity':quantity},[],{'gold':60,'items':{'ether':1}},'The supplies are put to use before you leave. The road is safer for the next traveler.'),
 ('road','The broken watch' if region=='ravenwood' else 'Danger on the approach','Defeat the alpha wolf inside Blackthorn’s fort.' if region=='ravenwood' else 'Clear the threat at '+r['roads'][1]+'.',{'kind':'encounter','stage':101 if region=='ravenwood' else 100},[],{'gold':55,'items':{'potion':2}},'The watch gathers its wounded and sets the next signal. You have earned the right to carry their trust.'),
 ('threshold','Beyond the threshold','Clear '+r['chambers'][0]+' inside '+r['dungeon']+'.',{'kind':'encounter','stage':0},[],{'gold':65,'items':{'entropic_essence':1}},'The first seal opens. The damage reaches deeper than the road, but the anchor can still be restored.'),
 ('anchor',r['objective'].rstrip('.'),r['objective'],{'kind':'cleared'},['signs','threshold'],{'gold':100,'items':{'entropic_essence':2}},'The anchor answers. '+line_a+' '+line_b),
 ('oath','Two duties, one journey','Recruit one guardian; leave the other to defend '+r['name']+'.',{'kind':'recruit'},['anchor'],{'gold':80,'items':{'ether':2}},'One guardian joins the expedition. The other takes the watch. Neither duty can be left undone.')]
 for key,title,objective,goal,requires,reward,conclusion in entries:
  qid=region+':'+key
  quests[qid]={'id':qid,'region':region,'title':title,'objective':objective,'goal':goal,'requires':[region+':'+x for x in requires],'reward':reward,'conclusion':conclusion}
  if key=='anchor':quests[qid]['choices']=[{'id':'roads','label':choice_a,'text':line_a,'items':{'potion':3}},{'id':'watch','label':choice_b,'text':line_b,'items':{'iron_ingot':3}}]
# The finale has distinct milestones rather than delivery errands.
for stage in range(3):
 qid='deep:front'+str(stage)
 quests[qid]={'id':qid,'region':'deep','title':campaign['regions']['deep']['chambers'][stage],'objective':'Hold this front with three companions who have not fought a previous final front.','goal':{'kind':'final','stage':stage+1},'requires':[] if stage==0 else ['deep:front'+str(stage-1)],'reward':{'gold':100,'items':{'ether':2}},'conclusion':['The threshold holds. The first three companions keep the way open.','The World Serpent falls. A second company holds the path to the heart.','The heart is quiet. Nine companions have held the world together.'][stage]}
(root/'game/data/quests.json').write_text(json.dumps({'schema':1,'draft_content':True,'quests':quests,'sites':sites,'dialogue':dialogue},indent=2,ensure_ascii=False)+'\n')
print(f'Built {len(quests)} quests, {sum(map(len,sites.values()))} discovery sites and {len(dialogue)} regional conversations')
